from typing import List

class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x: int, y: int) -> bool:
        xr = self.find(x)
        yr = self.find(y)
        if xr == yr:
            return False
        if self.rank[xr] < self.rank[yr]:
            self.parent[xr] = yr
        elif self.rank[xr] > self.rank[yr]:
            self.parent[yr] = xr
        else:
            self.parent[yr] = xr
            self.rank[xr] += 1
        return True

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        # Map each value to its index
        val_to_idx = {v: i for i, v in enumerate(nums)}

        # Initialize DSU for all nodes
        dsu = DSU(n)

        # Only values <= threshold can have edges
        # Present array for quick lookup
        if threshold > 0:
            present = [False] * (threshold + 1)
            for v in nums:
                if v <= threshold:
                    present[v] = True

            # Precompute divisors for all numbers 1..threshold
            divisors = [[] for _ in range(threshold + 1)]
            for i in range(1, threshold + 1):
                for j in range(i, threshold + 1, i):
                    divisors[j].append(i)

            # For each x, union all present divisors
            for x in range(1, threshold + 1):
                # Find first present divisor
                first_idx = -1
                for d in divisors[x]:
                    if present[d]:
                        if first_idx == -1:
                            first_idx = val_to_idx[d]
                        else:
                            dsu.union(first_idx, val_to_idx[d])

        # Count distinct roots
        roots = set()
        for i in range(n):
            roots.add(dsu.find(i))
        return len(roots)

